Fix the Insecure Direct Object Reference (IDOR) vulnerability.

```
# Python Flask - VULNERABLE
@app.route('/api/user/<int:user_id>')
def get_user(user_id):
    user = db.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone()
    return jsonify(user)
```

```
# Python Flask - PATCHED (Authorization Check)
from flask_login import current_user, login_required

@app.route('/api/user/<int:user_id>')
@login_required
def get_user(user_id):
    # Only allow users to access their own data (or admins)
    if current_user.id != user_id and not current_user.is_admin:
        return jsonify({'error': 'Unauthorized'}), 403

    user = db.execute("SELECT id, username, email FROM users WHERE id=?",
                      (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404

    return jsonify(user)

# Fix: 1) Added @login_required decorator
#       2) Authorization check: user can only access own data
#       3) Admin override for legitimate admin access
#       4) Only return non-sensitive fields (no password hash)
#       5) 404 for missing users to prevent enumeration
```

Add security headers to this Express.js application.

```
// Express.js - NO SECURITY HEADERS
const express = require('express');
const app = express();

app.get('/', (req, res) => {
    res.send('Hello World');
});

app.listen(3000);
```

```
// Express.js - PATCHED (Security Headers with Helmet)
const express = require('express');
const helmet = require('helmet');
const app = express();

// Add security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            imgSrc: ["'self'", "data:"],
        },
    },
    crossOriginEmbedderPolicy: true,
    crossOriginOpenerPolicy: true,
    crossOriginResourcePolicy: { policy: "same-site" },
    dnsPrefetchControl: true,
    frameguard: { action: 'deny' },
    hidePoweredBy: true,
    hsts: { maxAge: 31536000, includeSubDomains: true },
    ieNoOpen: true,
    noSniff: true,
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
    xssFilter: true,
}));

app.get('/', (req, res) => {
    res.send('Hello World');
});

app.listen(3000);

// Fix: Added helmet middleware with comprehensive security headers:
// - CSP prevents XSS and data injection
// - HSTS enforces HTTPS
// - X-Frame-Options prevents clickjacking
// - X-Content-Type-Options prevents MIME sniffing
```

